SELECT s.* FROM warehouse_bin_stock s
WHERE s.bin_id = #{binId}
  AND s.sku_id = #{skuId}
  AND s.batch_no = #{batchNo}
FOR UPDATE


SELECT s.* FROM warehouse_bin_stock s
JOIN warehouse_bin b ON b.bin_id = s.bin_id
WHERE b.warehouse_id = #{warehouseId}
  AND s.sku_id = #{skuId}
  AND s.batch_no = #{batchNo}
  AND s.quantity > 0
ORDER BY s.expiry_date ASC NULLS LAST, s.bin_id ASC
FOR UPDATE OF s
